#!/usr/bin/env python3
"""Mirror Tier A project memory between the Mac and Windows slugs.

Claude Code keys project memory by a slug built from the absolute path, so the
same project has two folders under ~/.claude/projects: `-Users-kristinarash-DEV-X`
(Mac) and `C--Users-eric-rash-Desktop-DEV-X` (Windows). dotclaude syncs both
folders to both machines, but each machine only auto-loads its own, so a memory
written on one machine is invisible to sessions on the other.

This pairs the folders and makes every pair hold the same files:
  - a file one side lacks is copied over
  - a file both sides have with different content: the newer one wins on both
    sides (frontmatter `modified:`, else last git commit, else mtime). The older
    version stays in dotclaude's git history.
  - MEMORY.md is merged, not replaced: every index line from either side is
    kept, keyed by the file it links to.
Nothing is deleted. Subfolders (e.g. `_archive/`) are left alone.

Usage: python mirror_memory.py [--dry-run]
Stdlib only; runs the same on both machines.
"""
import argparse
import re
import subprocess
from datetime import datetime, timezone
from pathlib import Path

CLAUDE = Path.home() / ".claude"
PROJECTS = CLAUDE / "projects"

MAC_HOME, WIN_HOME = "-Users-kristinarash", "C--Users-eric-rash"
MAC_DEV, WIN_DEV = MAC_HOME + "-DEV", WIN_HOME + "-Desktop-DEV"

INDEX = "MEMORY.md"
ENTRY = re.compile(r"^\s*-\s*\[[^\]]*\]\(([^)]+)\)")
EPOCH = datetime.min.replace(tzinfo=timezone.utc)


def side(slug):
    s = slug.lower()
    if s.startswith(MAC_HOME.lower()):
        return "mac"
    if s.startswith(WIN_HOME.lower()):
        return "win"
    return None


def pair_key(slug):
    """Machine-neutral key: '' for the home folder, '-dev-...' for DEV projects.

    Underscores fold to dashes and case is ignored because older Claude Code
    versions kept `_` in slugs and some Windows sessions got a lowercase drive
    letter, so one project can have `..._CampPrep` and `...-CampPrep` variants.
    """
    k = slug.lower().replace("_", "-")
    s = side(slug)
    if s == "mac":
        rest = k[len(MAC_HOME):]
    elif s == "win":
        rest = k[len(WIN_HOME):]
        if rest == "-desktop-dev" or rest.startswith("-desktop-dev-"):
            rest = rest[len("-desktop"):]
        elif rest == "-dev" or rest.startswith("-dev-"):
            return None
    else:
        return None
    if rest == "" or rest == "-dev" or rest.startswith("-dev-"):
        return rest
    return None  # OneDrive-era and other one-off slugs have no twin


def twin_slug(src_slug, target_side):
    """Folder name the other machine's Claude Code will use for this project."""
    if pair_key(src_slug) == "":
        return MAC_HOME if target_side == "mac" else WIN_HOME
    prefix_len = len(MAC_DEV) if side(src_slug) == "mac" else len(WIN_DEV)
    suffix = re.sub(r"[^A-Za-z0-9]", "-", src_slug[prefix_len:])
    return (MAC_DEV if target_side == "mac" else WIN_DEV) + suffix


def norm(data):
    return data.replace(b"\r\n", b"\n").strip()


def parse_time(text):
    try:
        return datetime.fromisoformat(text.strip().strip("'\"").replace("Z", "+00:00"))
    except ValueError:
        return None


def modified(path):
    head = path.read_text(encoding="utf-8", errors="replace").splitlines()[:40]
    for line in head:
        m = re.match(r"\s*modified:\s*(\S+)", line)
        if m and (t := parse_time(m.group(1))):
            return t if t.tzinfo else t.replace(tzinfo=timezone.utc)
    out = subprocess.run(
        ["git", "-C", str(CLAUDE), "log", "-1", "--format=%cI", "--", str(path.relative_to(CLAUDE))],
        capture_output=True, text=True,
    ).stdout.strip()
    if out and (t := parse_time(out)):
        return t
    return datetime.fromtimestamp(path.stat().st_mtime, timezone.utc)


def description(path):
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines()[:20]:
        m = re.match(r"\s*description:\s*(.+)", line)
        if m:
            return m.group(1).strip().strip("'\"")
    return "mirrored from the other machine"


def merge_index(dirs, final_files):
    """Newest MEMORY.md is the base; append the other sides' entries it lacks."""
    versions = [(modified(d / INDEX), d / INDEX) for d in dirs if (d / INDEX).is_file()]
    versions.sort(key=lambda v: v[0], reverse=True)
    if versions:
        lines = versions[0][1].read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n").rstrip("\n").split("\n")
    else:
        lines = ["# Memory Index", ""]
    linked = {m.group(1) for ln in lines if (m := ENTRY.match(ln))}
    for _, p in versions[1:]:
        for ln in p.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n").split("\n"):
            m = ENTRY.match(ln)
            if m and m.group(1) not in linked:
                lines.append(ln)
                linked.add(m.group(1))
    for name, path in sorted(final_files.items()):
        if name not in linked:
            lines.append(f"- [{path.stem}]({name}) — {description(path)}")
    return ("\n".join(lines) + "\n").encode("utf-8")


def mirror(dry_run):
    groups = {}
    for d in sorted(PROJECTS.iterdir()):
        if (d / "memory").is_dir() and (k := pair_key(d.name)) is not None:
            groups.setdefault(k, []).append(d)

    totals = {"copied": 0, "replaced": 0, "indexes": 0, "created": 0}
    for key, slug_dirs in sorted(groups.items()):
        dirs = [d / "memory" for d in slug_dirs]
        sides = {side(d.name) for d in slug_dirs}
        for missing in {"mac", "win"} - sides:
            new = PROJECTS / twin_slug(slug_dirs[0].name, missing) / "memory"
            if not any(p.is_file() for p in dirs[0].iterdir()):
                continue
            print(f"  + create {new.parent.name}")
            totals["created"] += 1
            if not dry_run:
                new.mkdir(parents=True, exist_ok=True)
            dirs.append(new)

        names = {p.name for d in dirs if d.is_dir() for p in d.iterdir() if p.is_file() and p.name != INDEX}
        final = {}
        for name in sorted(names):
            have = [(modified(d / name), d / name) for d in dirs if (d / name).is_file()]
            have.sort(key=lambda v: v[0], reverse=True)
            winner = have[0][1]
            final[name] = winner
            data = winner.read_bytes()
            for d in dirs:
                target = d / name
                if target.is_file() and norm(target.read_bytes()) == norm(data):
                    continue
                verb = "replaced" if target.is_file() else "copied"
                totals[verb] += 1
                if verb == "replaced":
                    print(f"  ~ {key or '(home)'}/{name}: newer {side(winner.parent.parent.name)} version wins")
                if not dry_run:
                    target.write_bytes(data)

        merged = merge_index(dirs, final)
        for d in dirs:
            target = d / INDEX
            if target.is_file() and norm(target.read_bytes()) == norm(merged):
                continue
            totals["indexes"] += 1
            if not dry_run:
                target.write_bytes(merged)

    mode = "DRY RUN, nothing written" if dry_run else "written"
    print(
        f"memory mirror ({mode}): {len(groups)} projects paired, "
        f"{totals['copied']} files copied, {totals['replaced']} replaced by a newer version, "
        f"{totals['indexes']} MEMORY.md merged, {totals['created']} twin folders created"
    )


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--dry-run", action="store_true")
    mirror(ap.parse_args().dry_run)

