        f"memory mirror ({mode}): {len(groups)} projects paired, "
        f"{totals['copied']} files copied, {totals['replaced']} replaced by a newer version, "
        f"{totals['indexes']} MEMORY.md merged, {totals['created']} twin folders created"
    )


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--dry-run", action="store_true")
    mirror(ap.parse_args().dry_run)

